parameters.jsCode:
// GENERATED preamble — every unit in the estate starts here, identically.
// Rejects an envelope whose MAJOR version this unit does not implement, rather than
// half-processing a shape it does not understand.
const SUPPORTED_MAJOR = 1;
const raw = $json.envelope ?? $json;
const v = String(raw.envelope_version ?? '0.0.0');
if (Number(v.split('.')[0]) !== SUPPORTED_MAJOR) {
  throw new Error('VALIDATION_FAILED: envelope_version ' + v + ' is not supported by intake.message.normalize@1.0.0 (needs ' + SUPPORTED_MAJOR + '.x)');
}
for (const f of ['trace_id', 'tenant_id', 'idempotency_key']) {
  if (!raw[f]) throw new Error('VALIDATION_FAILED: envelope.' + f + ' is required');
}
if (raw.deadline_at && Date.parse(raw.deadline_at) < Date.now()) {
  // Fail fast rather than start work that cannot finish in time.
  throw new Error('TIMEOUT: deadline_at ' + raw.deadline_at + ' already passed before intake.message.normalize started');
}
return [{ json: {
  ...raw,
  span_id: 'spn_' + Math.random().toString(36).slice(2, 10),
  parent_span_id: raw.span_id ?? null,
  policy: raw.policy ?? {},
  budget: raw.budget ?? {},
  provenance: raw.provenance ?? [],
  _started_at: Date.now(),
  _capability: "intake.message.normalize",
  _capability_version: "1.0.0"
} }];

// GENERATED telemetry — span_start.
const e = $json;
return [{ json: { ...e, _telemetry: {
  event_id: 'evt_' + Math.random().toString(36).slice(2, 12),
  trace_id: e.trace_id, span_id: e.span_id, parent_span_id: e.parent_span_id,
  tenant_id: e.tenant_id, brand_id: e.brand_id ?? null, vertical: e.vertical ?? null,
  capability: "intake.message.normalize", capability_version: "1.0.0",
  layer: "terminal", stage: e.stage ?? null,
  event: 'span_start', at: new Date().toISOString()
} } }];

const p = $json.payload || {};
const src = p.source_channel || 'unknown';
let text = '', author = null, media = [], ref = null;

switch (src) {
  case 'telegram': {
    const m = p.raw?.message || {};
    text = m.text || m.caption || '';
    author = String(m.from?.id ?? '');
    ref = String(m.message_id ?? '');
    if (m.voice) media.push({ kind: 'audio', provider_file_id: m.voice.file_id, duration_s: m.voice.duration });
    if (m.photo?.length) media.push({ kind: 'image', provider_file_id: m.photo[m.photo.length - 1].file_id });
    if (m.document) media.push({ kind: 'doc', provider_file_id: m.document.file_id, mime: m.document.mime_type });
    break;
  }
  case 'slack': { text = p.raw?.event?.text || ''; author = p.raw?.event?.user || null; ref = p.raw?.event?.ts || null; break; }
  case 'email': { text = [p.raw?.subject, p.raw?.body].filter(Boolean).join('\n\n'); author = p.raw?.from || null; ref = p.raw?.message_id || null; break; }
  case 'web_form': { text = Object.entries(p.raw || {}).map(([k, v]) => k + ': ' + v).join('\n'); ref = p.raw?.submission_id || null; break; }
  case 'crm_event': { text = p.raw?.description || JSON.stringify(p.raw || {}); ref = p.raw?.event_id || null; break; }
  case 'schedule': { text = p.prompt || ''; ref = p.schedule_id || null; break; }
  case 'api': { text = p.text || ''; ref = p.request_id || null; break; }
  default: { text = typeof p.raw === 'string' ? p.raw : JSON.stringify(p.raw ?? p); }
}

return [{ json: {
  source: { channel: src, author, raw_ref: ref, received_at: new Date().toISOString() },
  text: String(text).trim(),
  media,
  modality: media.some(m => m.kind === 'audio') ? 'voice' : (media.length ? 'rich' : 'text'),
  needs_transcription: media.some(m => m.kind === 'audio')
} }];

// Runs before ANY text reaches a model. Redaction at the boundary is the only
// placement that actually holds: once raw text is in a prompt it is in a log somewhere.
if ($('Envelope In').first().json.policy?.pii_redaction === false) return [{ json: $json }];
const PATTERNS = [
  [/[\w.+-]+@[\w-]+\.[\w.]+/g, '[email]'],
  [/\+?\d[\d\s().-]{7,}\d/g, '[phone]'],
  [/\b(?:\d[ -]*?){13,16}\b/g, '[card]'],
  [/\b\d{3}-\d{2}-\d{4}\b/g, '[ssn]']
];
let text = $json.text || '';
let hits = 0;
for (const [re, tok] of PATTERNS) { text = text.replace(re, () => { hits++; return tok; }); }
return [{ json: { ...$json, text, pii_redactions: hits } }];

// GENERATED epilogue — appends exactly one provenance entry and closes the span.
// Provenance is append-only; nothing in the estate is permitted to rewrite an earlier entry.
const e = $('Envelope In').first().json;
const out = $json;
const duration = Date.now() - (e._started_at ?? Date.now());
const entry = {
  capability: "intake.message.normalize",
  version: "1.0.0",
  at: new Date().toISOString(),
  duration_ms: duration,
  model: out._model ?? null,
  provider: out._provider ?? null,
  cost_minor_units: out._cost_minor_units ?? 0,
  inputs_hash: e.idempotency_key,
  decision_id: out.decision?.decision_id ?? null
};
return [{ json: {
  ...out,
  _envelope: {
    ...e,
    span_id: e.parent_span_id,
    provenance: [...(e.provenance ?? []), entry],
    budget: { ...(e.budget ?? {}), spent_minor_units: (e.budget?.spent_minor_units ?? 0) + (entry.cost_minor_units ?? 0) }
  },
  _telemetry: {
    event_id: 'evt_' + Math.random().toString(36).slice(2, 12),
    trace_id: e.trace_id, span_id: e.span_id, tenant_id: e.tenant_id,
    capability: "intake.message.normalize", capability_version: "1.0.0",
    layer: "terminal", event: 'span_end', status: out.error ? 'error' : 'ok',
    duration_ms: duration, cost_minor_units: entry.cost_minor_units,
    error_code: out.error?.code ?? null, at: new Date().toISOString()
  }
} }];

